import { test, expect } from '@playwright/test';

test.describe('Notification Count Reset', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display notification count', async ({ page }) => {
    const notificationCount = await page.getByRole('status', { name: /notification count/i });
    expect(await notificationCount.textContent()).toBe('3'); // Assuming there are 3 notifications initially
  });

  test('should reset notification count to zero after reading all messages', async ({ page }) => {
    const readAllButton = page.getByRole('button', { name: /read all/i });
    await readAllButton.click();

    const notificationCount = await page.getByRole('status', { name: /notification count/i });
    expect(await notificationCount.textContent()).toBe('0');
  });
});
